<template><div class="app-shell"><header class="topbar" v-if="screen!=='guide'"><button v-if="canGoBack" class="icon-btn" @click="goBack">‹</button><div class="brand"><span class="brand-mark">C</span><span>Ciwaan</span></div><button class="icon-btn" @click="openSettings">⚙</button></header><main class="screen"><section v-if="screen==='home'" class="home-screen"><div class="hero-mark"><span>C</span><i/></div><p class="eyebrow">DIGITAL ADDRESSING</p><h1>Give any place<br><strong>a simple address.</strong></h1><p class="hero-copy">Create a shareable Ciwaan for a home, business, meeting point, or anywhere you need someone to find.</p><div class="home-actions"><button class="primary large" @click="startCreate">Create Ciwaan <span>→</span></button><button class="secondary large" @click="openFind">Find a Ciwaan <span>⌕</span></button></div><div class="privacy-note">⌖ <span>Your location is only used when you choose to create or navigate to a Ciwaan.</span></div></section><section v-else-if="screen==='choose'" class="map-flow"><div id="create-map" class="map"/><div class="center-pin"><span/></div><button class="locate-floating" @click="useCurrentLocation">⌖</button><div class="sheet"><div class="grabber"/><p class="eyebrow">STEP 1 OF 3</p><h2>Choose your location</h2><p class="muted">Move the map until the center point is exactly where you want your Ciwaan.</p><div class="precision-grid"><button class="precision active" @click="precision='exact'"><b>⌖ Exact location</b><small>Share the precise point</small><em>✓</em></button><button class="precision compact" @click="precision='general'"><b>General location</b><small>Share the nearby area</small><em>{{precision==='general'?'✓':''}}</em></button></div><button class="primary" @click="confirmLocation">Continue →</button></div></section><section v-else-if="screen==='confirm'" class="map-flow"><div id="confirm-map" class="map"/><div class="sheet"><div class="grabber"/><p class="eyebrow">STEP 2 OF 3</p><h2>Is this the right place?</h2><div class="coordinates">⌖ <div><b>{{coords.lat.toFixed(6)}}, {{coords.lng.toFixed(6)}}</b><small>{{precision==='exact'?'Exact location':'General area'}}</small></div></div><button class="primary" @click="screen='name'">Confirm location →</button><button class="text-btn" @click="screen='choose'">Adjust location</button></div></section><section v-else-if="screen==='name'" class="content-screen centered"><div class="step-badge">03</div><p class="eyebrow">FINAL STEP</p><h2>What should we call this place?</h2><p class="muted">Use a name you'll recognize when you share it later.</p><div class="field"><input v-model="label" maxlength="60" placeholder="My Home" @keyup.enter="createCiwaan"/><span>{{label.length}}/60</span></div><div class="chips"><button @click="label='My Home'">Home</button><button @click="label='My Office'">Office</button><button @click="label='Meeting Point'">Meeting point</button><button @click="label='My Shop'">Shop</button></div><button class="primary large" :disabled="!label.trim()||creating" @click="createCiwaan">{{creating?'Creating…':'Create my Ciwaan'}}</button><p class="tiny">By creating a Ciwaan, you agree to the <button class="link" @click="screen='privacy'">Privacy Policy</button>.</p></section><section v-else-if="screen==='created'" class="content-screen created"><div class="success">✓</div><p class="eyebrow">ADDRESS READY</p><h2>Your Ciwaan is ready.</h2><div class="code-card"><small>{{created.label}}</small><strong>{{created.code}}</strong><span>{{created.precision==='exact'?'Exact location':'General location'}}</span></div><div class="stack"><button class="whatsapp" @click="shareWhatsApp(created)">◉ Share on WhatsApp</button><div class="split"><button @click="copyCiwaan">Copy Ciwaan</button><button @click="openQr">Show QR</button></div><button class="primary large" @click="guideTo(created)">🧭 Guide Me</button></div><button class="text-btn" @click="screen='home'">Done</button></section><section v-else-if="screen==='find'" class="content-screen"><p class="eyebrow">FIND A PLACE</p><h2>Where are you going?</h2><p class="muted">Enter a Ciwaan code to open its location.</p><div class="search-box"><span>⌕</span><input v-model="searchCode" placeholder="CW-8K4P-29" @keyup.enter="lookup"/><button @click="lookup">Go</button></div><div v-if="error" class="error">{{error}}</div><div class="recent" v-if="recent.length"><b>Recent</b><button v-for="item in recent" :key="item.code" class="row" @click="showAddress(item)"><span>⌖</span><span><strong>{{item.label}}</strong><small>{{item.code}}</small></span>›</button></div></section><section v-else-if="screen==='address'" class="address-screen"><div id="address-map" class="address-map"/><div class="address-sheet"><div class="address-title"><div class="big-pin">⌖</div><div><p class="eyebrow">CIWAAN</p><h2>{{activeAddress.label}}</h2><strong>{{activeAddress.code}}</strong></div></div><div class="meta"><span>📍 {{activeAddress.precision==='exact'?'Exact location':'General area'}}</span><span>{{formatCoords(activeAddress.latitude,activeAddress.longitude)}}</span></div><button class="primary large" @click="guideTo(activeAddress)">🧭 Guide Me</button><div class="split"><button @click="shareWhatsApp(activeAddress)">◉ WhatsApp</button><button @click="copyAddress(activeAddress)">Copy address</button></div></div></section><section v-else-if="screen==='guide'" class="guide-screen"><div id="guide-map" class="map"/><div class="guide-top"><button class="round" @click="stopGuide">×</button><div class="pill">{{navStatus}}</div></div><div class="guide-bottom"><div v-if="routing" class="loading"><span/>Calculating the easiest walking route…</div><template v-else><div class="summary"><div><strong>{{distanceText}}</strong><small>remaining</small></div><div><strong>{{etaText}}</strong><small>estimated</small></div><div><strong>🚶</strong><small>walking</small></div></div><div class="turn"><span>↑</span><div><b>{{instruction}}</b><small>{{nextTurnDistance}}</small></div></div><button class="end" @click="stopGuide">End Guide</button></template></div></section><section v-else-if="screen==='explore'" class="content-screen"><p class="eyebrow">DISCOVER</p><h2>Explore nearby</h2><p class="muted">A simple map view for nearby public Ciwaans.</p><div id="explore-map" class="explore-map"/></section><section v-else-if="screen==='saved'" class="content-screen"><p class="eyebrow">YOUR PLACES</p><h2>Saved</h2><p class="muted">Ciwaans created on this device.</p><div v-if="saved.length"><button v-for="item in saved" :key="item.code" class="row" @click="showAddress(item)"><span>⌖</span><span><strong>{{item.label}}</strong><small>{{item.code}}</small></span>›</button></div><div v-else class="empty"><div>⌖</div><h3>Nothing saved yet</h3><p>Create a Ciwaan and it will appear here.</p><button class="primary" @click="startCreate">Create Ciwaan</button></div></section><section v-else-if="screen==='settings'" class="content-screen"><p class="eyebrow">APP</p><h2>Settings</h2><div class="settings"><div><b>Location permissions</b><small>Allow Ciwaan to use your location for maps and Guide Me.</small><button @click="requestLocation">Allow</button></div><div><b>Privacy</b><small>Read exactly what Ciwaan collects and why.</small><button @click="screen='privacy'">View</button></div><div><b>My Ciwaans</b><small>Manage addresses stored on this device.</small><button @click="screen='saved'">Open</button></div></div></section><section v-else-if="screen==='privacy'" class="content-screen privacy"><p class="eyebrow">YOUR PRIVACY</p><h2>Privacy Policy</h2><p class="policy-date">Effective: August 27, 2026</p><article><h3>1. What Ciwaan does</h3><p>Ciwaan creates shareable digital addresses for physical locations and provides map-based navigation. You can use the app without an account.</p><h3>2. Location data</h3><p>When you choose to create an address, Ciwaan may request device location permission. If granted, GPS coordinates are used to place the map. Guide Me uses live device location while navigation is active so the app can show position, route, distance and progress.</p><h3>3. What we store</h3><p>When you create a Ciwaan, we store the address code, place name, selected latitude and longitude, precision setting and timestamps. We do not require your name, email, phone number, password or account.</p><h3>4. Public sharing</h3><p>A Ciwaan is designed to be shared. Anyone with a valid code or link can retrieve the location associated with that public address. Do not create an exact Ciwaan for a location you do not want to disclose.</p><h3>5. General location</h3><p>General location reduces precision but does not guarantee anonymity. Choose the least precise setting that still serves your purpose.</p><h3>6. Navigation</h3><p>Live location is used while Guide Me is active. Ciwaan does not need to create a permanent movement history. Route endpoints may be sent to the routing service used by the app.</p><h3>7. Third-party infrastructure</h3><p>Ciwaan uses third-party map and routing infrastructure. Those providers may process technical requests and geographic coordinates according to their own policies.</p><h3>8. Security</h3><p>Public address records are protected behind a server-side API and database row-level security. The no-account management credential is stored locally on the creating device and is not public.</p><h3>9. Retention</h3><p>Addresses remain available until deleted or removed under operational or legal policies. Temporary anti-abuse information is designed to expire after a short period.</p><h3>10. Children</h3><p>Ciwaan is not directed to children under 13 and does not knowingly collect personal information from children under 13.</p><h3>11. Your choices</h3><p>You can deny location permission, stop Guide Me at any time, and choose General instead of Exact location.</p><h3>12. Changes</h3><p>This policy may be updated when the service or legal requirements change. Material changes will update the effective date.</p><h3>13. Contact</h3><p>Privacy requests should use the current contact method published with the Ciwaan service or its official distribution listing.</p><p class="policy-note">This policy describes the product's intended data practices and is not a substitute for jurisdiction-specific legal advice.</p></article></section></main><nav class="bottom-nav" v-if="!['guide','privacy','choose','confirm','name','created'].includes(screen)"><button :class="{active:screen==='home'}" @click="screen='home'">⌂<span>Home</span></button><button :class="{active:screen==='explore'}" @click="openExplore">⌖<span>Explore</span></button><button :class="{active:screen==='saved'}" @click="screen='saved'">♡<span>Saved</span></button></nav><footer class="made-by">Made by Rising Tech</footer><div v-if="showQr" class="modal" @click.self="showQr=false"><div class="modal-card"><button class="modal-close" @click="showQr=false">×</button><p class="eyebrow">SCAN TO FIND</p><h3>{{created.code}}</h3><canvas ref="qrCanvas" class="qr-canvas"/><p class="muted">Scan to open this Ciwaan.</p></div></div><div v-if="toast" class="toast">{{toast}}</div></div></template>
<script setup>
import {computed,nextTick,onMounted,ref} from 'vue'
import L from 'leaflet';import QRCode from 'qrcode';import 'leaflet/dist/leaflet.css'
const SUPABASE_URL='https://dpiwdhtbhwjgatvcfkcb.supabase.co',SUPABASE_KEY='sb_publishable_PSZnTEo74jObih_6TTpXVQ_tJwzTnXY',API=`${SUPABASE_URL}/functions/v1/ciwaan-api`,PUBLIC_BASE_URL='https://raazimtech.github.io/ciwaan/'
const screen=ref('home'),precision=ref('exact'),label=ref(''),creating=ref(false),error=ref(''),toast=ref(''),searchCode=ref(''),coords=ref({lat:9.56,lng:44.06}),created=ref(null),activeAddress=ref(null),showQr=ref(false),qrCanvas=ref(null),recent=ref(JSON.parse(localStorage.getItem('ciwaan_recent')||'[]')),saved=ref(JSON.parse(localStorage.getItem('ciwaan_saved')||'[]')),routing=ref(true),navStatus=ref('Finding your route'),distanceText=ref('—'),etaText=ref('—'),instruction=ref('Follow the route'),nextTurnDistance=ref('');let createMap,confirmMap,addressMap,guideMap,exploreMap,routeLine,userMarker,watchId
const canGoBack=computed(()=>!['home','explore','saved','find','settings'].includes(screen.value));function goBack(){screen.value='home'}function openSettings(){screen.value='settings'}function startCreate(){error.value='';precision.value='exact';screen.value='choose';nextTick(initCreateMap)}function openFind(){error.value='';searchCode.value='';screen.value='find'}function openExplore(){screen.value='explore';nextTick(initExploreMap)}
function baseMap(id,lat,lng,z=16){const m=L.map(id,{zoomControl:false}).setView([lat,lng],z);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(m);L.control.zoom({position:'topright'}).addTo(m);return m}function initCreateMap(){if(createMap)createMap.remove();createMap=baseMap('create-map',coords.value.lat,coords.value.lng);createMap.on('moveend',()=>{const c=createMap.getCenter();coords.value={lat:c.lat,lng:c.lng}})}function initConfirmMap(){if(confirmMap)confirmMap.remove();confirmMap=baseMap('confirm-map',coords.value.lat,coords.value.lng,17);L.marker([coords.value.lat,coords.value.lng]).addTo(confirmMap)}function initAddressMap(){if(addressMap)addressMap.remove();addressMap=baseMap('address-map',activeAddress.value.latitude,activeAddress.value.longitude,17);L.marker([activeAddress.value.latitude,activeAddress.value.longitude]).addTo(addressMap)}function initExploreMap(){if(exploreMap)exploreMap.remove();exploreMap=baseMap('explore-map',coords.value.lat,coords.value.lng,14)}
function useCurrentLocation(){if(!navigator.geolocation){toast.value='Location is not supported on this device.';return}navigator.geolocation.getCurrentPosition(p=>{coords.value={lat:p.coords.latitude,lng:p.coords.longitude};if(createMap)createMap.setView([coords.value.lat,coords.value.lng],17);if(exploreMap)exploreMap.setView([coords.value.lat,coords.value.lng],15)},()=>toast.value='Location permission was not granted.',{enableHighAccuracy:true,timeout:10000,maximumAge:10000})}function requestLocation(){useCurrentLocation();toast.value='Location permission requested.'}function confirmLocation(){screen.value='confirm';nextTick(initConfirmMap)}
async function api(payload){const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','apikey':SUPABASE_KEY},body:JSON.stringify(payload)}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Something went wrong.');return d}
async function createCiwaan(){if(!label.value.trim())return;creating.value=true;error.value='';try{const d=await api({action:'create',label:label.value.trim(),latitude:coords.value.lat,longitude:coords.value.lng,precision:precision.value});created.value=d.address;localStorage.setItem(`ciwaan_token_${d.address.code}`,d.managementToken);saved.value=[d.address,...saved.value.filter(x=>x.code!==d.address.code)].slice(0,50);recent.value=[d.address,...recent.value.filter(x=>x.code!==d.address.code)].slice(0,20);localStorage.setItem('ciwaan_saved',JSON.stringify(saved.value));localStorage.setItem('ciwaan_recent',JSON.stringify(recent.value));screen.value='created'}catch(e){error.value=e.message}finally{creating.value=false}}
async function lookup(){const code=searchCode.value.trim().toUpperCase();if(!code)return;error.value='';try{const d=await api({action:'lookup',code});showAddress(d.address)}catch(e){error.value=e.message}}function showAddress(a){activeAddress.value=a;recent.value=[a,...recent.value.filter(x=>x.code!==a.code)].slice(0,20);localStorage.setItem('ciwaan_recent',JSON.stringify(recent.value));screen.value='address';nextTick(initAddressMap)}function formatCoords(a,b){return `${Number(a).toFixed(5)}, ${Number(b).toFixed(5)}`}function shareUrl(a){return `${PUBLIC_BASE_URL}?code=${encodeURIComponent(a.code)}`}function shareWhatsApp(a=created.value){if(!a)return;const text=`📍 My Ciwaan\n${a.code}\n${a.label}\n\nFind me here:\n${shareUrl(a)}`;window.open(`https://wa.me/?text=${encodeURIComponent(text)}`,'_blank','noopener')}async function copyText(t){try{await navigator.clipboard.writeText(t);toast.value='Copied to clipboard.'}catch{toast.value='Copy is not available.'}}function copyCiwaan(){copyText(created.value.code)}function copyAddress(a){copyText(`${a.label} — ${a.code}\n${shareUrl(a)}`)}function openQr(){showQr.value=true;nextTick(()=>QRCode.toCanvas(qrCanvas.value,shareUrl(created.value),{width:180,margin:1,color:{dark:'#101817',light:'#ffffff'}}))}
async function guideTo(a){activeAddress.value=a;screen.value='guide';routing.value=true;navStatus.value='Finding your route';await nextTick();if(guideMap)guideMap.remove();guideMap=baseMap('guide-map',coords.value.lat,coords.value.lng,16);if(!navigator.geolocation){routing.value=false;return}navigator.geolocation.getCurrentPosition(async p=>{const s={lat:p.coords.latitude,lng:p.coords.longitude};coords.value=s;userMarker=L.circleMarker([s.lat,s.lng],{radius:8,color:'#087f5b',fillColor:'#fff',fillOpacity:1,weight:4}).addTo(guideMap);L.marker([a.latitude,a.longitude]).addTo(guideMap);await fetchRoute(s,a)},()=>{routing.value=false;toast.value='Please allow location access to use Guide Me.'},{enableHighAccuracy:true,timeout:12000,maximumAge:5000});watchId=navigator.geolocation.watchPosition(p=>{coords.value={lat:p.coords.latitude,lng:p.coords.longitude};if(userMarker)userMarker.setLatLng([p.coords.latitude,p.coords.longitude])},()=>{}, {enableHighAccuracy:true,maximumAge:2000,timeout:10000})}
async function fetchRoute(s,a){try{const u=`https://routing.openstreetmap.de/routed-foot/route/v1/driving/${s.lng},${s.lat};${a.longitude},${a.latitude}?overview=full&geometries=geojson&steps=true`,r=await fetch(u),d=await r.json(),rt=d.routes?.[0];if(!rt)throw Error();if(routeLine)guideMap.removeLayer(routeLine);routeLine=L.geoJSON(rt.geometry,{style:{color:'#087f5b',weight:7,opacity:.9}}).addTo(guideMap);guideMap.fitBounds(routeLine.getBounds(),{padding:[30,160]});distanceText.value=rt.distance<1000?`${Math.round(rt.distance)} m`:`${(rt.distance/1000).toFixed(1)} km`;etaText.value=`${Math.max(1,Math.round(rt.duration/60))} min`;const st=rt.legs?.[0]?.steps?.find(x=>x.maneuver?.type!=='depart')||rt.legs?.[0]?.steps?.[0];instruction.value=st?.name?`${pretty(st.maneuver?.type)} ${st.name}`:'Follow the route';nextTurnDistance.value=st?`${Math.round(st.distance)} m ahead`:'';navStatus.value='Guiding you';routing.value=false}catch{routing.value=false;navStatus.value='Route unavailable';instruction.value='Follow the map to your destination';toast.value='The route service is temporarily unavailable.'}}function pretty(t){return({turn:'Turn',roundabout:'Enter roundabout',fork:'Keep at the fork',merge:'Merge'})[t]||'Continue on'}function stopGuide(){if(watchId)navigator.geolocation.clearWatch(watchId);watchId=null;if(guideMap)guideMap.remove();guideMap=null;screen.value='address';nextTick(initAddressMap)}onMounted(()=>{const c=new URLSearchParams(location.search).get('code');if(c){searchCode.value=c;openFind();nextTick(lookup)}})
</script>